import { useEffect, useRef, useState } from "react";
import {
  ArrowUpRight,
//   BriefcaseBusiness,
  CheckCircle2,
  ClipboardCheck,
  FileText,
  Search,
  Users,
  UserRound,
} from "lucide-react";

/* =========================================================
   REVEAL ANIMATION
========================================================= */

function Reveal({
  children,
  className = "",
}: {
  children: React.ReactNode;
  className?: string;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    const element = ref.current;

    if (!element) {
      return undefined;
    }

    const observer = new IntersectionObserver(
      (entries) => {
        const entry = entries[0];

        if (entry && entry.isIntersecting) {
          setVisible(true);
          observer.disconnect();
        }
      },
      {
        threshold: 0.12,
      }
    );

    observer.observe(element);

    return () => {
      observer.disconnect();
    };
  }, []);

  return (
    <div
      ref={ref}
      className={`transition-all duration-700 ease-out ${
        visible
          ? "translate-y-0 opacity-100"
          : "translate-y-8 opacity-0"
      } ${className}`}
    >
      {children}
    </div>
  );
}

/* =========================================================
   SECTION LABEL
========================================================= */

function SectionNumber({
  number,
  label,
}: {
  number: string;
  label: string;
}) {
  return (
    <div className="flex items-center gap-4">
      <span className="font-mono text-[11px] text-neutral-400">
        {number}
      </span>

      <span className="text-[12px] font-medium uppercase tracking-[0.16em] text-neutral-400">
        {label}
      </span>
    </div>
  );
}

/* =========================================================
   PROCESS CARD
========================================================= */

function ProcessCard({
  number,
  title,
  description,
  icon: Icon,
}: {
  number: string;
  title: string;
  description: string;
  icon: React.ElementType;
}) {
  return (
    <div className="group border-b border-r border-black/[0.08] p-6 transition-all duration-300 hover:-translate-y-1 hover:bg-white dark:border-white/[0.08] dark:hover:bg-[#191919] sm:p-7">
      <div className="flex items-start justify-between">
        <span className="font-mono text-[11px] text-neutral-400">
          {number}
        </span>

        <Icon
          size={19}
          strokeWidth={1.5}
          className="text-neutral-400 transition-transform duration-300 group-hover:scale-110"
        />
      </div>

      <h3 className="mt-12 text-[18px] font-medium tracking-[-0.02em]">
        {title}
      </h3>

      <p className="mt-3 text-[14px] leading-6 text-neutral-500 dark:text-neutral-400">
        {description}
      </p>
    </div>
  );
}

/* =========================================================
   UI PLACEHOLDER
========================================================= */

function ProductPreview({
  type,
}: {
  type: "dashboard" | "candidate" | "job";
}) {
  if (type === "dashboard") {
    return (
      <div className="relative aspect-[16/9] overflow-hidden border border-black/[0.08] bg-[#ece9e4] p-3 dark:border-white/[0.08] dark:bg-[#191919] sm:p-5">
        <div className="h-full rounded-lg border border-black/[0.07] bg-white p-4 shadow-sm dark:border-white/[0.07] dark:bg-[#222]">
          <div className="flex gap-2">
            <div className="h-2 w-20 rounded-full bg-neutral-200 dark:bg-neutral-700" />
            <div className="h-2 w-12 rounded-full bg-neutral-100 dark:bg-neutral-800" />
          </div>

          <div className="mt-5 grid grid-cols-3 gap-3">
            <div className="h-16 rounded-lg bg-neutral-100 dark:bg-neutral-800" />
            <div className="h-16 rounded-lg bg-neutral-100 dark:bg-neutral-800" />
            <div className="h-16 rounded-lg bg-neutral-100 dark:bg-neutral-800" />
          </div>

          <div className="mt-4 grid grid-cols-[1.5fr_1fr] gap-3">
            <div className="h-28 rounded-lg bg-neutral-100 dark:bg-neutral-800" />
            <div className="h-28 rounded-lg bg-neutral-100 dark:bg-neutral-800" />
          </div>
        </div>
      </div>
    );
  }

  if (type === "candidate") {
    return (
      <div className="relative aspect-[16/9] overflow-hidden border border-black/[0.08] bg-[#ece9e4] p-3 dark:border-white/[0.08] dark:bg-[#191919] sm:p-5">
        <div className="mx-auto h-full max-w-[560px] rounded-lg border border-black/[0.07] bg-white p-5 shadow-sm dark:border-white/[0.07] dark:bg-[#222]">
          <div className="flex items-center gap-4">
            <div className="h-12 w-12 rounded-full bg-neutral-200 dark:bg-neutral-700" />

            <div>
              <div className="h-2.5 w-28 rounded-full bg-neutral-800 dark:bg-neutral-200" />
              <div className="mt-2 h-2 w-20 rounded-full bg-neutral-200 dark:bg-neutral-700" />
            </div>
          </div>

          <div className="mt-6 grid grid-cols-2 gap-3">
            <div className="h-20 rounded-lg bg-neutral-100 dark:bg-neutral-800" />
            <div className="h-20 rounded-lg bg-neutral-100 dark:bg-neutral-800" />
          </div>

          <div className="mt-4 h-16 rounded-lg bg-neutral-100 dark:bg-neutral-800" />
        </div>
      </div>
    );
  }

  return (
    <div className="relative aspect-[16/9] overflow-hidden border border-black/[0.08] bg-[#ece9e4] p-3 dark:border-white/[0.08] dark:bg-[#191919] sm:p-5">
      <div className="mx-auto h-full max-w-[650px] rounded-lg border border-black/[0.07] bg-white p-5 shadow-sm dark:border-white/[0.07] dark:bg-[#222]">
        <div className="h-3 w-36 rounded-full bg-neutral-800 dark:bg-neutral-200" />

        <div className="mt-6 grid grid-cols-2 gap-4">
          <div className="space-y-3">
            <div className="h-3 w-full rounded bg-neutral-100 dark:bg-neutral-800" />
            <div className="h-3 w-4/5 rounded bg-neutral-100 dark:bg-neutral-800" />
            <div className="h-3 w-3/5 rounded bg-neutral-100 dark:bg-neutral-800" />
          </div>

          <div className="rounded-lg bg-neutral-100 dark:bg-neutral-800" />
        </div>

        <div className="mt-5 h-10 rounded-lg bg-neutral-900 dark:bg-neutral-100" />
      </div>
    </div>
  );
}

/* =========================================================
   MAIN CASE STUDY
========================================================= */

export default function EduHire() {
  return (
    <div className="min-h-screen bg-[#f7f5f2] text-neutral-950 transition-colors duration-300 dark:bg-[#111111] dark:text-neutral-100">
      <div className="mx-auto min-h-screen w-full max-w-[1180px] border-x border-black/[0.06] dark:border-white/[0.07]">

        {/* =================================================
            HERO
        ================================================= */}

        <section className="px-5 pb-24 pt-16 sm:px-8 sm:pb-28 sm:pt-24 lg:px-14 lg:pt-28">
          <Reveal>
            <div className="flex items-center gap-3 text-[11px] font-medium uppercase tracking-[0.18em] text-neutral-400 sm:text-[13px]">
              <span className="h-2 w-2 rounded-full bg-neutral-950 dark:bg-white" />

              EduHire
            </div>
          </Reveal>

          <Reveal className="mt-7 sm:mt-8">
            <h1 className="max-w-[950px] font-serif text-[50px] leading-[0.98] tracking-[-0.045em] sm:text-[70px] lg:text-[90px]">
              Making hiring feel clearer, faster and more human.
            </h1>
          </Reveal>

          <Reveal className="mt-7 max-w-[680px] sm:mt-8">
            <p className="text-[17px] leading-7 text-neutral-500 dark:text-neutral-400 sm:text-[20px] sm:leading-8">
              A recruitment platform designed to simplify the journey
              between discovering opportunities, evaluating
              candidates and moving the right people forward.
            </p>
          </Reveal>

          {/* Project information */}
          <Reveal className="mt-10 sm:mt-12">
            <div className="grid grid-cols-2 gap-y-7 border-y border-black/[0.1] py-6 dark:border-white/[0.1] sm:grid-cols-4 sm:py-7">
              <div>
                <p className="text-[10px] uppercase tracking-[0.15em] text-neutral-400 sm:text-[12px]">
                  Role
                </p>

                <p className="mt-2 text-[13px] sm:text-[15px]">
                  UX/UI & Product Designer
                </p>
              </div>

              <div>
                <p className="text-[10px] uppercase tracking-[0.15em] text-neutral-400 sm:text-[12px]">
                  Product
                </p>

                <p className="mt-2 text-[13px] sm:text-[15px]">
                  Recruitment Platform
                </p>
              </div>

              <div>
                <p className="text-[10px] uppercase tracking-[0.15em] text-neutral-400 sm:text-[12px]">
                  Focus
                </p>

                <p className="mt-2 text-[13px] sm:text-[15px]">
                  UX · UI · Product Strategy
                </p>
              </div>

              <div>
                <p className="text-[10px] uppercase tracking-[0.15em] text-neutral-400 sm:text-[12px]">
                  Platform
                </p>

                <p className="mt-2 text-[13px] sm:text-[15px]">
                  Web
                </p>
              </div>
            </div>
          </Reveal>

          {/* Hero product preview */}
          <Reveal className="mt-14 sm:mt-20">
            <div className="overflow-hidden bg-white p-1.5 shadow-[0_20px_80px_rgba(0,0,0,0.06)] dark:bg-[#191919] sm:p-2">
              <ProductPreview type="dashboard" />
            </div>
          </Reveal>
        </section>

        {/* =================================================
            PROBLEM
        ================================================= */}

        <section className="border-t border-black/[0.08] px-5 py-24 dark:border-white/[0.08] sm:px-8 sm:py-28 lg:px-14">
          <Reveal>
            <SectionNumber number="01" label="The problem" />

            <div className="mt-10 grid gap-10 lg:grid-cols-[1fr_1.5fr] lg:gap-12">
              <h2 className="font-serif text-[38px] leading-[1.05] tracking-[-0.035em] sm:text-[52px]">
                Hiring had too many disconnected steps.
              </h2>

              <div className="space-y-5 text-[16px] leading-7 text-neutral-500 dark:text-neutral-400 sm:text-[18px] sm:leading-8">
                <p>
                  Recruitment involves several different decisions:
                  finding relevant opportunities, understanding a
                  candidate's profile, reviewing applications and
                  deciding what happens next.
                </p>

                <p>
                  When those steps are presented as separate
                  interactions, users have to repeatedly interpret
                  information and understand what action they should
                  take next.
                </p>

                <p className="font-medium text-neutral-950 dark:text-neutral-100">
                  The opportunity was to make the journey feel like
                  one connected experience.
                </p>
              </div>
            </div>
          </Reveal>
        </section>

        {/* =================================================
            INSIGHT
        ================================================= */}

        <section className="px-5 py-24 sm:px-8 sm:py-28 lg:px-14">
          <Reveal>
            <SectionNumber number="02" label="The insight" />

            <div className="mt-10 max-w-[950px]">
              <p className="font-serif text-[38px] leading-[1.1] tracking-[-0.035em] sm:text-[54px]">
                The interface should help users understand what to
                do next.
              </p>

              <p className="mt-7 max-w-[680px] text-[16px] leading-7 text-neutral-500 dark:text-neutral-400 sm:text-[18px] sm:leading-8">
                Instead of treating jobs, candidates and applications
                as isolated pieces of information, I structured the
                experience around the user's next decision.
              </p>
            </div>
          </Reveal>
        </section>

        {/* =================================================
            DESIGN APPROACH
        ================================================= */}

        <section className="border-y border-black/[0.08] py-24 dark:border-white/[0.08] sm:py-28">
          <div className="px-5 sm:px-8 lg:px-14">
            <Reveal>
              <SectionNumber number="03" label="Design approach" />

              <div className="mt-10 grid gap-10 lg:grid-cols-[1fr_1.5fr] lg:gap-12">
                <h2 className="font-serif text-[38px] leading-[1.05] tracking-[-0.035em] sm:text-[52px]">
                  Reduce friction at every decision point.
                </h2>

                <p className="text-[16px] leading-7 text-neutral-500 dark:text-neutral-400 sm:text-[18px] sm:leading-8">
                  I focused on information hierarchy, clear calls to
                  action and consistent patterns across the
                  experience. The goal was not to add more
                  functionality, but to make the existing journey
                  easier to understand.
                </p>
              </div>
            </Reveal>

            <Reveal className="mt-12 sm:mt-16">
              <div className="grid grid-cols-1 border-l border-t border-black/[0.08] dark:border-white/[0.08] sm:grid-cols-2 lg:grid-cols-4">
                <ProcessCard
                  number="01"
                  title="Discover"
                  description="Help users quickly find relevant opportunities and information."
                  icon={Search}
                />

                <ProcessCard
                  number="02"
                  title="Understand"
                  description="Surface the information needed to evaluate a job or candidate."
                  icon={FileText}
                />

                <ProcessCard
                  number="03"
                  title="Evaluate"
                  description="Create clearer comparison and decision-making moments."
                  icon={ClipboardCheck}
                />

                <ProcessCard
                  number="04"
                  title="Move forward"
                  description="Make the next action obvious and reduce unnecessary steps."
                  icon={ArrowUpRight}
                />
              </div>
            </Reveal>
          </div>
        </section>

        {/* =================================================
            USER FLOW
        ================================================= */}

        <section className="px-5 py-24 sm:px-8 sm:py-28 lg:px-14">
          <Reveal>
            <SectionNumber number="04" label="User flow" />

            <h2 className="mt-10 max-w-[850px] font-serif text-[38px] leading-[1.05] tracking-[-0.035em] sm:text-[54px]">
              A connected journey from discovery to decision.
            </h2>

            <div className="mt-12 overflow-hidden border border-black/[0.08] dark:border-white/[0.08]">
              <div className="grid grid-cols-1 md:grid-cols-4">
                {[
                  {
                    number: "01",
                    title: "Discover",
                    description:
                      "Browse and identify relevant opportunities.",
                    icon: Search,
                  },
                  {
                    number: "02",
                    title: "Profile",
                    description:
                      "Understand the person, role and requirements.",
                    icon: UserRound,
                  },
                  {
                    number: "03",
                    title: "Evaluate",
                    description:
                      "Review information and make an informed decision.",
                    icon: ClipboardCheck,
                  },
                  {
                    number: "04",
                    title: "Action",
                    description:
                      "Move the candidate or application to the next step.",
                    icon: CheckCircle2,
                  },
                ].map((item) => {
                  const Icon = item.icon;

                  return (
                    <div
                      key={item.number}
                      className="group border-b border-black/[0.08] p-6 last:border-b-0 dark:border-white/[0.08] md:border-b-0 md:border-r md:last:border-r-0 sm:p-7"
                    >
                      <div className="flex items-center justify-between">
                        <span className="font-mono text-[11px] text-neutral-400">
                          {item.number}
                        </span>

                        <Icon
                          size={18}
                          strokeWidth={1.5}
                          className="text-neutral-400 transition-transform duration-300 group-hover:scale-110"
                        />
                      </div>

                      <h3 className="mt-12 text-[18px] font-medium">
                        {item.title}
                      </h3>

                      <p className="mt-3 text-[14px] leading-6 text-neutral-500 dark:text-neutral-400">
                        {item.description}
                      </p>
                    </div>
                  );
                })}
              </div>
            </div>
          </Reveal>
        </section>

        {/* =================================================
            KEY SCREENS
        ================================================= */}

        <section className="border-t border-black/[0.08] py-24 dark:border-white/[0.08] sm:py-28">
          <div className="px-5 sm:px-8 lg:px-14">
            <Reveal>
              <SectionNumber number="05" label="Key screens" />

              <div className="mt-10 max-w-[800px]">
                <h2 className="font-serif text-[38px] leading-[1.05] tracking-[-0.035em] sm:text-[54px]">
                  Designed around the moments that matter.
                </h2>
              </div>
            </Reveal>

            {/* Dashboard */}
            <Reveal className="mt-14 sm:mt-20">
              <div className="grid gap-8 lg:grid-cols-[1fr_0.65fr] lg:items-center">
                <div className="overflow-hidden bg-white p-2 shadow-[0_15px_50px_rgba(0,0,0,0.05)] dark:bg-[#191919]">
                  <ProductPreview type="dashboard" />
                </div>

                <div className="lg:pl-8">
                  <span className="font-mono text-[11px] text-neutral-400">
                    01
                  </span>

                  <h3 className="mt-4 font-serif text-[32px] tracking-[-0.03em]">
                    Overview
                  </h3>

                  <p className="mt-4 text-[16px] leading-7 text-neutral-500 dark:text-neutral-400">
                    The overview brings the most important information
                    together so users can understand the current
                    state of their hiring activity without navigating
                    through multiple screens.
                  </p>
                </div>
              </div>
            </Reveal>

            {/* Candidate */}
            <Reveal className="mt-20 sm:mt-28">
              <div className="grid gap-8 lg:grid-cols-[0.65fr_1fr] lg:items-center">
                <div className="order-2 lg:order-1 lg:pr-8">
                  <span className="font-mono text-[11px] text-neutral-400">
                    02
                  </span>

                  <h3 className="mt-4 font-serif text-[32px] tracking-[-0.03em]">
                    Candidate experience
                  </h3>

                  <p className="mt-4 text-[16px] leading-7 text-neutral-500 dark:text-neutral-400">
                    Candidate information is organized around the
                    questions users need to answer when evaluating a
                    profile, reducing the need to scan disconnected
                    sections.
                  </p>
                </div>

                <div className="order-1 overflow-hidden bg-white p-2 shadow-[0_15px_50px_rgba(0,0,0,0.05)] dark:bg-[#191919] lg:order-2">
                  <ProductPreview type="candidate" />
                </div>
              </div>
            </Reveal>

            {/* Job */}
            <Reveal className="mt-20 sm:mt-28">
              <div className="grid gap-8 lg:grid-cols-[1fr_0.65fr] lg:items-center">
                <div className="overflow-hidden bg-white p-2 shadow-[0_15px_50px_rgba(0,0,0,0.05)] dark:bg-[#191919]">
                  <ProductPreview type="job" />
                </div>

                <div className="lg:pl-8">
                  <span className="font-mono text-[11px] text-neutral-400">
                    03
                  </span>

                  <h3 className="mt-4 font-serif text-[32px] tracking-[-0.03em]">
                    Job experience
                  </h3>

                  <p className="mt-4 text-[16px] leading-7 text-neutral-500 dark:text-neutral-400">
                    Job information is structured so users can
                    quickly understand requirements, expectations and
                    the next action without unnecessary visual noise.
                  </p>
                </div>
              </div>
            </Reveal>
          </div>
        </section>

        {/* =================================================
            EDGE CASES
        ================================================= */}

        <section className="border-t border-black/[0.08] px-5 py-24 dark:border-white/[0.08] sm:px-8 sm:py-28 lg:px-14">
          <Reveal>
            <SectionNumber number="06" label="Edge cases" />

            <div className="mt-10 grid gap-10 lg:grid-cols-[0.8fr_2fr] lg:gap-12">
              <h2 className="font-serif text-[38px] leading-[1.05] tracking-[-0.035em] sm:text-[52px]">
                The experience also needs to work when nothing goes
                perfectly.
              </h2>

              <div className="grid gap-px bg-black/[0.08] dark:bg-white/[0.08] sm:grid-cols-2">
                {[
                  {
                    title: "No results",
                    text: "Give users a clear explanation and a useful next action when no relevant jobs or candidates are found.",
                  },
                  {
                    title: "Incomplete profile",
                    text: "Make missing information visible without overwhelming the user.",
                  },
                  {
                    title: "Different application states",
                    text: "Clearly distinguish new, reviewed, shortlisted and completed states.",
                  },
                  {
                    title: "Empty dashboard",
                    text: "Use meaningful empty states instead of leaving users with unexplained blank areas.",
                  },
                ].map((item) => (
                  <div
                    key={item.title}
                    className="bg-[#f7f5f2] p-6 transition-all duration-300 hover:-translate-y-1 hover:bg-white dark:bg-[#111111] dark:hover:bg-[#191919] sm:p-7"
